ALTER TABLE "USERS" ADD "IS_ACTIVE" NUMBER(1) DEFAULT 1;
CREATE TABLE "COMMENTS" (
    "ID" NUMBER DEFAULT "TESTSCHEMA"."ISEQ$$_73616".nextval NOT NULL,
    "POST_ID" NUMBER NOT NULL,
    "USER_ID" NUMBER NOT NULL,
    "CONTENT" CLOB NOT NULL,
    "CREATED_AT" TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE "COMMENTS" ADD CONSTRAINT "SYS_C008971" PRIMARY KEY (ID);

ALTER TABLE "COMMENTS" ADD CONSTRAINT "FK_COMMENT_USER" FOREIGN KEY ("USER_ID") REFERENCES "USERS" ("ID");
ALTER TABLE "COMMENTS" ADD CONSTRAINT "FK_POST" FOREIGN KEY ("POST_ID") REFERENCES "POSTS" ("ID");
ALTER TABLE "POSTS" ADD CONSTRAINT "CHECK_TITLE_LENGTH" CHECK (LENGTH(TITLE) > 0);
CREATE INDEX "IDX_USERS_EMAIL" ON "USERS" ("EMAIL" ASC);
